// src/ui/ui_layout.h - the shared Game Boy UI layout, as data.
//
// The tables themselves are generated by scripts/build_ui.py from ui/mpcboy_ui.json into
// src/ui/generated/ui_layout.inc and src/ui/generated/pixel_font.inc (committed; re-run the
// script after editing the JSON or the art code). They are walked from the same in-memory
// component tree that becomes the MPC's Plugin Skins/TUI.json, so slot bounds, widget
// sub-bounds and segment positions are never retyped.
//
// Coordinates are design units: a tab is kTabWidth x kTabHeight (generated); the Mac editor draws
// one point per unit.
// Colours are 0xAARRGGBB. Film strips are vertical; width/height in Asset are one frame.
// Platform-free and header-only: no allocation, no dependencies beyond <cstdint>.
#pragma once

#include <cstdint>

namespace mpcboy::ui {

struct Rect
{
    int x, y, w, h;
};

// The component a control instantiates (gen_ui's definition name without the "Menu" suffix).
enum class WidgetKind : std::uint8_t
{
    SliderWithFocus,
    KnobUni,
    KnobBi,
    FaderUni,
    FaderBi,
    Toggle,
    Radio2,
    Radio3,
    Radio4
};

// A child widget inside a component definition (TUI.json componentData.type).
enum class ChildType : std::uint8_t
{
    Focus,
    Slider,
    Knob,
    Label,
    Button,
    Image,
    KnobOverlay,
    MenuOverlay
};

enum class LabelKind : std::uint8_t { None, Name, Value, Text };
enum class Justify : std::uint8_t { Left, Right, Centre };
enum class Drag : std::uint8_t { None, Vertical, Horizontal };
enum class PanelKind : std::uint8_t { LcdTable, LcdChannel };
enum class DynamicKind : std::uint8_t { FilmStrip, ValueLabel };
// Q-Links.json "Bank Direction" (ui-reference 8.3).
enum class BankDirection : std::uint8_t { Column, ColumnBottomUp, Row, RowTopDown };

struct Theme
{
    // From the "mpc" style (also used by the MPC skin): overlay field, focus, values, names.
    std::uint32_t background, accent, text, muted;
    // Roles from the Game Boy palette ("gb.palette").
    std::uint32_t bezel, plate, rubber, shell, magenta;
    std::uint32_t lcdField, lcdInk, lcdCursor, lcdCursorInk, lcdPlayhead, lcdPlayheadInk, lcdBeat;
    std::uint32_t cartridge, tabOnText;
};

struct Asset
{
    const char* file;   // under ui/art/ (MPC: Plugin Skins/, Mac: Contents/Resources/ui/)
    int width, height;  // one frame
    int frames;         // 1 for a still image
};

struct ChildDef
{
    const char* name;
    ChildType type;
    Rect bounds;               // relative to the control's slot (overlays: the full screen)
    bool onlyWhenFocused;      // whenVisible "WhenFocussed" (the focus ring)
    const char* image;         // Knob film strip / Button on-image; nullptr if none
    const char* offImage;      // Button off-image; nullptr if none
    int frames;                // film-strip frames (1 otherwise)
    Drag drag;                 // Knob drag orientation
    int buttonId;              // Button: the step this button represents
    int buttonsInGroup;        // Button: 1 = toggle, N = radio group
    LabelKind label;
    std::uint32_t colour;      // Label colour
    float fontHeight;          // Label font height (MPC: Nexa Bold, upper case)
    Justify justify;
};

struct ComponentDef
{
    const char* name;  // TUI.json localComponentDefinitions key, e.g. "knobBi", "sliderWithFocusMenu"
    const ChildDef* children;
    int numChildren;
};

struct VisibleWhen
{
    int param;   // driving parameter index, or -1: always visible
    int choice;  // visible while that parameter's step equals this choice
    int count;   // number of choices of the driving parameter
};

struct Caption
{
    const char* text;  // segment caption (one per choice)
    Rect bounds;       // tab coordinates
    float fontHeight;  // MPC label font height (selects the editor's font scale: labelScale)
};

struct Control
{
    int param;               // parameter index
    const char* paramName;   // the name the plugin reports for that index (drift check)
    WidgetKind kind;
    bool menu;               // opens the menu overlay instead of the knob overlay
    int component;           // index into kComponents
    Rect slot;               // tab coordinates
    VisibleWhen visibleWhen;
    const Caption* captions;
    int numCaptions;
    std::uint32_t accent;    // the control's kit colour (page colour, or its own on MAIN's strips)
    int qlink;               // hardware Q-Link 1..16 on this tab, 0 when the Q-Link drives another control
};

struct Panel
{
    PanelKind kind;
    Rect bounds;  // tab coordinates
    const char* image;
};

// A parameter-bound decoration (MPC: Image FilmStrip or Label type Value, device-gated by
// "gb.mpcDynamics"; the editor draws them from the same data).
struct Dynamic
{
    DynamicKind kind;
    int param;               // parameter index
    const char* paramName;   // the name the plugin reports for that index (drift check)
    Rect bounds;             // tab coordinates
    const char* image;       // FilmStrip: the strip; nullptr for a label
    int frames;              // FilmStrip frames (= the parameter's steps)
    std::uint32_t colour;    // ValueLabel colour
    float fontHeight;        // ValueLabel font height (selects the editor's font scale)
    Justify justify;
    bool editor;             // false: inside the TABLE LCD, where the editor draws its live grid
};

struct Page
{
    const char* name;        // MPC tab name
    const char* title;       // page title drawn in the background art and the editor tab
    const char* background;  // full-tab background image
    const Control* controls; // overlapped slots (complementary visibleWhen) appear as two controls
    int numControls;
    const Panel* panels;
    int numPanels;
    std::uint32_t accent;    // page colour (channel colour; MAIN and TABLE: the DMG accent)
    const Dynamic* dynamics;
    int numDynamics;
};

struct TabBar
{
    Rect bounds;  // window coordinates
    const char* background;
    const char* onImage;
    const char* offImage;
    int firstButtonX;  // relative to bounds; button i is at firstButtonX + i * pitch
    int buttonY;       // relative to bounds
    int pitch;
};

struct TableColumn
{
    const char* title;
    int x;      // character column
    int chars;  // characters of data
};

// The TABLE page LCD. textX / textY / charScale are the MPC art's text origin and scale (its header
// row and printed command card); the Mac editor's live grid is positioned by gridLayout() from the
// generated kGrid* constants below it.
struct TableGrid
{
    int page;             // index into kPages
    Rect panelBounds;     // tab coordinates of the LCD panel
    int textX, textY;     // tab coordinates of the MPC art's header row's first character cell
    int charScale;        // MPC art: design units per font pixel
    const char* panelImage;
    const char* cursorImage;
    const TableColumn* columns;
    int numColumns;
};

// One section of the channel LCD: panel-relative x and width (design units).
struct LcdSection
{
    int x, w;
};

struct PixelGlyph
{
    char ch;
    std::uint8_t rows[7];  // bit 4 = leftmost column
};

#include "generated/ui_layout.inc"
#include "generated/pixel_font.inc"

}  // namespace mpcboy::ui
